def sha(p):
    h=hashlib.sha256()
    with p.open('rb') as f:
        for chunk in iter(lambda:f.read(8*1024*1024),b''):h.update(chunk)
    return h.hexdigest()
def save():
    (OUT/'archive-checks.json').write_text(json.dumps({'verified':plans,'zip_candidates':candidates,'elapsed_s':time.time()-start},ensure_ascii=False,indent=2),encoding='utf-8')
