                save();print(json.dumps({'verified_extracted_archive':str(p),'GiB':round(st.st_size/2**30,3),'members':len(verified)},ensure_ascii=False),flush=True)
    except (OSError,zipfile.BadZipFile,RuntimeError) as e:
        print(json.dumps({'archive':str(p),'error':type(e).__name__},ensure_ascii=False),flush=True)
save();print(json.dumps({'verified_count':len(plans),'reclaimable_GiB':sum(x['bytes'] for x in plans)/2**30,'elapsed_s':time.time()-start}),flush=True)
