      rd(NULL, CRU + 0x330) != 0x00400177 ||
      (rd(NULL, CRU + 0x334) & 3) != 3 ||
      (rd(NULL, CRU + 0x3b8) & 0xfff) != 0x100 ||
      (rd(NULL, 0x26046400) & 2) ||
