int sha256_vector(size_t, const uint8_t *[], const size_t *, uint8_t *);
}

namespace {
std::atomic<bool> active{false}, stop_requested{false};
std::atomic<uint32_t> next_epoch{1};
uint64_t now_us() {
  timespec t{};
  if (clock_gettime(CLOCK_MONOTONIC, &t)) return 0;
  return uint64_t(t.tv_sec) * 1000000 + t.tv_nsec / 1000;
}
int hash(const void *data, size_t bytes, uint8_t output[32], void *) {
  const uint8_t *blocks[] = {static_cast<const uint8_t *>(data)};
  return sha256_vector(1, blocks, &bytes, output);
}
struct Job {
  k7_voice_ring ring{};
  k7_voice_packer packer{};
  k7_duplex_stream_config config{};
  k7_duplex_stream_result result{};
  std::atomic<bool> done{false};
  int rc = 0;
};
int microphone(void *p, int16_t value, uint64_t index) {
  return k7_voice_packer_sample(&static_cast<Job *>(p)->packer, value, index);
}
int no_playback(void *, int16_t *) { return 0; }
int stop(void *) { return stop_requested.load(std::memory_order_acquire); }
void *capture(void *p) {
  auto *job = static_cast<Job *>(p);
  job->rc = k7sound_duplex_stream16(&job->config, &job->result);
  const int tail = k7_voice_packer_flush(&job->packer);
  if (!job->rc && tail) job->rc = tail;
  job->done.store(true, std::memory_order_release);
  return nullptr;
}
struct ActiveGuard {
  ~ActiveGuard() { active.store(false, std::memory_order_release); }
};
struct RuntimeDeleter { void operator()(k7_kws_runtime *p) { k7_kws_destroy(p); } };
struct AffinityGuard {
  cpu_set_t previous{};
  bool changed = false;
  int pin_consumer() {
    if (sched_getaffinity(0, sizeof(previous), &previous)) return -errno;
    cpu_set_t cpu; CPU_ZERO(&cpu); CPU_SET(0, &cpu);
    if (sched_setaffinity(0, sizeof(cpu), &cpu)) return -errno;
    changed = true;
    return 0;
  }
  ~AffinityGuard() {
    if (changed) (void)sched_setaffinity(0, sizeof(previous), &previous);
  }
};
}

extern "C" int k7kws_main(int argc, char **argv) {
  if (argc == 2 && !std::strcmp(argv[1], "stop")) {
    stop_requested.store(true, std::memory_order_release);
    std::printf("KWS stop_requested=1 active=%d\n", int(active.load()));
    return 0;
  }
  const bool model_only = argc == 2 && !std::strcmp(argv[1], "model-check");
  unsigned seconds = 0;
  if (!model_only && argc == 3 && !std::strcmp(argv[1], "probe")) {
    char *end = nullptr;
    unsigned long parsed = std::strtoul(argv[2], &end, 10);
    if (end && !*end && parsed >= 1 && parsed <= 30) seconds = unsigned(parsed);
  }
  if (!model_only && !seconds) {
    std::puts("k7kws model-check | probe <1..30 seconds> | stop");
    return 1;
  }
  bool expected = false;
  if (!active.compare_exchange_strong(expected, true)) return 1;
  ActiveGuard guard;
  stop_requested.store(false);
  AffinityGuard affinity;
  if (affinity.pin_consumer()) return 1;
  k7_kws_config config{};
  int rc = k7_kws_embedded_config(&config, hash, nullptr);
  k7_kws_runtime *raw = nullptr;
  const uint64_t started = now_us();
  std::printf("KWS create start synthetic=%d\n", int(model_only));
  if (!rc) rc = k7_kws_create(&config, &raw);
  std::unique_ptr<k7_kws_runtime, RuntimeDeleter> runtime(raw);
  std::printf("KWS create result=%d elapsed_us=%llu\n", rc,
              (unsigned long long)(now_us() - started));
  if (rc) return 1;
  uint64_t feed_total = 0, max_feed = 0, samples = 0;
  unsigned frames = 0, hits = 0;
  auto feed = [&](const k7_voice_frame &f) {
    k7_kws_detection detection{};
    const uint64_t begin = now_us();
    int result = k7_kws_feed(runtime.get(), f.pcm, f.samples, f.first_sample,
                             f.epoch, &detection);
    const uint64_t duration = now_us() - begin;
    feed_total += duration;
    if (duration > max_feed) max_feed = duration;
    ++frames; samples += f.samples;
    if (result == 1) {
      ++hits;
      std::printf("KWS hit label=%s end_sample=%llu epoch=%u\n", detection.keyword,
                  (unsigned long long)detection.end_sample, detection.epoch);
    }
    return result < 0 ? result : 0;
  };
  if (model_only) {
    k7_voice_frame silence{};
    silence.samples = 320; silence.epoch = next_epoch.fetch_add(1);
    for (unsigned i = 0; i < 100 && !stop_requested.load() && !rc; ++i) {
      silence.first_sample = uint64_t(i) * 320;
      rc = feed(silence);
    }
    std::printf("KWS model_check result=%d synthetic=1 frames=%u hits=%u total_us=%llu max_feed_us=%llu\n",
      rc, frames, hits, (unsigned long long)feed_total, (unsigned long long)max_feed);
    return rc ? 1 : 0;
  }
  std::unique_ptr<Job> job(new (std::nothrow) Job);
  if (!job) return 1;
  k7_voice_ring_init(&job->ring);
  rc = k7_voice_packer_init(&job->packer, &job->ring, next_epoch.fetch_add(1), 0, 0);
  if (rc) return 1;
  job->config.max_capture_frames = seconds * 16000;
  job->config.microphone = microphone; job->config.microphone_arg = job.get();
  job->config.playback = no_playback; job->config.stop_all = stop;
  pthread_attr_t attr;
  if (pthread_attr_init(&attr)) return 1;
  cpu_set_t cpu; CPU_ZERO(&cpu); CPU_SET(1, &cpu);
  rc = pthread_attr_setstacksize(&attr, 32768);
  if (!rc) rc = pthread_attr_setaffinity_np(&attr, sizeof(cpu), &cpu);
  pthread_t thread;
  if (!rc) rc = pthread_create(&thread, &attr, capture, job.get());
  pthread_attr_destroy(&attr);
  if (rc) return 1;
  std::printf("KWS listening seconds=%u actions=0\n", seconds);
  for (;;) {
    k7_voice_frame frame{};
    int taken = k7_voice_ring_take(&job->ring, &frame);
    if (taken < 0) { rc = taken; stop_requested.store(true); break; }
    if (taken) {
      if (stop_requested.load()) break;
      rc = feed(frame);
      if (rc) { stop_requested.store(true); break; }
    } else if (job->done.load(std::memory_order_acquire)) break;
    else usleep(1000);
  }
  if (stop_requested.load()) k7_kws_request_cancel(runtime.get());
  const int joined = pthread_join(thread, nullptr);
  if (joined) {
    stop_requested.store(true);
    while (!job->done.load(std::memory_order_acquire)) usleep(1000);
    (void)pthread_detach(thread);
  }
  if (!rc) rc = job->rc;
  if (!rc && joined) rc = -joined;
  std::printf("KWS probe result=%d frames=%u samples=%llu hits=%u total_feed_us=%llu max_feed_us=%llu overflow=%u captured=%u rx_overflow=%u cleanup=%d/%d/%d\n",
      rc, frames, (unsigned long long)samples, hits, (unsigned long long)feed_total,
      (unsigned long long)max_feed, k7_voice_ring_overflows(&job->ring),
      job->result.captured, job->result.rx_overflows, job->result.codec_stop,
      job->result.platform_restore, job->result.i2c_restore);
  return rc ? 1 : 0;
}
