   * been made, so leave the transition intact and keep listening.  A changed
   * mode (HOLD/STOP) and genuine status failures retain their own errors. */
  if(rc==-EAGAIN)rc=expected==atomic_load(&s->epoch)?-EBUSY:-ECANCELED;
