namespace {
std::atomic_flag claimed = ATOMIC_FLAG_INIT;
std::atomic<bool> published{false};
k7_kws_assets active{};
int verify(const k7_kws_blob &blob, size_t limit,
           const k7_kws_config &config) {
  if (!blob.data || !blob.bytes || blob.bytes > limit) return -EINVAL;
  uint8_t actual[32]{};
  if (config.sha256(blob.data, blob.bytes, actual, config.sha256_context))
    return -EIO;
  uint8_t mismatch = 0;
  for (size_t i = 0; i < sizeof actual; ++i)
    mismatch |= actual[i] ^ blob.sha256[i];
  return mismatch ? -EBADMSG : 0;
}
}
extern "C" int k7_kws_assets_acquire(const k7_kws_config *config) {
  if (!config || !config->sha256) return -EINVAL;
  if (claimed.test_and_set(std::memory_order_acquire)) return -EBUSY;
  const auto &a = config->assets;
  int result = verify(a.encoder, 16u * 1024 * 1024, *config);
  if (!result) result = verify(a.decoder, 2u * 1024 * 1024, *config);
  if (!result) result = verify(a.joiner, 2u * 1024 * 1024, *config);
  if (!result) result = verify(a.tokens, 64u * 1024, *config);
  if (!result) result = verify(a.keywords, 16u * 1024, *config);
  if (result) {
    claimed.clear(std::memory_order_release);
    return result;
  }
  active = a;
  published.store(true, std::memory_order_release);
  return 0;
}
extern "C" void k7_kws_assets_release() {
  published.store(false, std::memory_order_release);
  active = {};
  claimed.clear(std::memory_order_release);
}
extern "C" int k7_kws_model_lookup(const char *uri, const void **data,
                                    size_t *bytes) {
  if (data) *data = nullptr;
  if (bytes) *bytes = 0;
  if (!uri || !data || !bytes) return -EINVAL;
  if (!published.load(std::memory_order_acquire)) return -ENOENT;
  const k7_kws_blob *blob = nullptr;
  if (!std::strcmp(uri, "k7ram:kws-encoder")) blob = &active.encoder;
  else if (!std::strcmp(uri, "k7ram:kws-decoder")) blob = &active.decoder;
  else if (!std::strcmp(uri, "k7ram:kws-joiner")) blob = &active.joiner;
  else return -ENOENT;
  *data = blob->data;
  *bytes = blob->bytes;
  return 0;
}
extern "C" int k7_kws_model_exists(const char *uri) {
  const void *data = nullptr;
  size_t bytes = 0;
  return k7_kws_model_lookup(uri, &data, &bytes) == 0;
}
