  if (!runtime) return -ENOMEM;
  runtime->backend = backend;
  runtime->guard_samples = uint64_t(config->duplicate_guard_ms) * 16;
  const int result = backend->open(config, &runtime->engine);
  if (result || !runtime->engine) {
    if (runtime->engine) backend->close(runtime->engine);
    delete runtime;
    return result ? result : -EIO;
