                             size_t count, uint64_t first, uint32_t epoch,
                             k7_kws_detection *detection) {
  if (detection) *detection = {};
  if (!runtime || !pcm || !detection || count == 0 || count > 320 ||
      first > std::numeric_limits<uint64_t>::max() - count) return -EINVAL;
  if (runtime->cancelled.load(std::memory_order_acquire)) return -ECANCELED;
  const auto *b = runtime->backend;
  if (runtime->have_frame &&
      (runtime->epoch != epoch || runtime->next_sample != first)) {
    const int result = b->reset(runtime->engine);
    if (result) return result;
    runtime->have_keyword = false;
  }
  float normalized[320];
  for (size_t i = 0; i < count; ++i) normalized[i] = float(pcm[i]) / 32768.0f;
  int result = b->accept(runtime->engine, normalized, count);
  if (result) return result;
  runtime->have_frame = true;
  runtime->epoch = epoch;
  runtime->next_sample = first + count;
  for (unsigned step = 0;; ++step) {
    if (runtime->cancelled.load(std::memory_order_acquire)) return -ECANCELED;
    const int ready = b->ready(runtime->engine);
    if (ready < 0) return ready;
    if (!ready) return 0;
    if (step == 8) { b->reset(runtime->engine); return -EOVERFLOW; }
    if ((result = b->decode(runtime->engine))) return result;
    if (runtime->cancelled.load(std::memory_order_acquire)) return -ECANCELED;
    char keyword[96]{};
    if ((result = b->result(runtime->engine, keyword, sizeof keyword)))
      return result;
    if (!keyword[0]) continue;
    /* Sherpa requires reset immediately after a hit, including a suppressed hit. */
    if ((result = b->reset(runtime->engine))) return result;
    if (runtime->have_keyword && !std::strcmp(keyword, runtime->last_keyword) &&
        runtime->next_sample - runtime->last_keyword_sample < runtime->guard_samples)
      return 0;
    std::memcpy(runtime->last_keyword, keyword, sizeof keyword);
    runtime->last_keyword_sample = runtime->next_sample;
    runtime->have_keyword = true;
    std::memcpy(detection->keyword, keyword, sizeof keyword);
    detection->end_sample = runtime->next_sample;
    detection->epoch = epoch;
    return 1;
  }
}
