  if(atomic_load(&s->tx_state)==K7_VOICE_TX_IDLE)k7_session_capture_tx_busy(s,true);
#endif
  if (!atomic_compare_exchange_strong(&s->tx_state, &expected, K7_VOICE_TX_RESETTING)) return unlock(s, -EBUSY);
